//! The commands, one file each. Generated by anything-anything from anything.toml.

pub mod args;
pub mod check;
pub mod rules;
pub mod scan;

use serde_json::Value;

/// What a command gives back: text for people, data for --json and MCP clients, and an exit code.
#[derive(Debug, Default)]
pub struct Output {
    pub text: String,
    pub data: Value,
    pub exit: u8,
}

#[allow(dead_code)]
impl Output {
    /// Text for people and data for machines.
    pub fn new(text: impl Into<String>, data: Value) -> Output {
        Output { text: text.into(), data, exit: 0 }
    }

    /// Text only.
    pub fn text(text: impl Into<String>) -> Output {
        Output::new(text, Value::Null)
    }

    /// Still prints, then exits with this code: for "it worked, and found problems".
    pub fn with_exit(mut self, code: u8) -> Output {
        self.exit = code;
        self
    }

    pub fn print(&self, json: bool) {
        if json {
            let data = if self.data.is_null() { serde_json::json!({ "text": self.text }) } else { self.data.clone() };
            println!("{}", serde_json::to_string_pretty(&data).unwrap_or_default());
        } else if !self.text.is_empty() {
            println!("{}", self.text.trim_end_matches('\n'));
        }
    }
}
